vec4 CubicHermite(vec4 A, vec4 B, vec4 C, vec4 D, float t)
{
        float t2 = t * t;
        float t3 = t * t*t;
        vec4 a = -A / 2.0 + (3.0*B) / 2.0 - (3.0*C) / 2.0 + D / 2.0;
        vec4 b = A - (5.0*B) / 2.0 + 2.0*C - D / 2.0;
        vec4 c = -A / 2.0 + C / 2.0;
        vec4 d = B;

        return a * t3 + b * t2 + c * t + d;
}


